 +RD_T(44,600,'P<tspan	dy=\".3em\"	font-size=\"72%\">t</tspan><tspan	dy=\"-.3em\"	font-size=\"72%\">​</tspan> × 16 (12 dB)',{fs:22,fw:800,fill:ORG})+`<rect x="250" y="580" width="130" height="28" rx="6" fill="${GRN}" fill-opacity=".45"/><rect x="250" y="580" width="260" height="28" rx="6" fill="none" stroke="${GRN}" stroke-width="3"/>`+RD_T(520,602,'R × 2',{fs:22,fw:800,fill:GRN})
